def item(skill, spec, n):
    qid=f'local:senior-foundations:physics:{skill["id"]}:q{n}'
    kind=spec.get('kind','short_answer')
    choices=spec.get('choices',[])
    ans=spec['answer']
    book=skill['book_id']; goal=skill['goal_ids'][0]
    q={'id':qid,'subject':'physics','stage':'senior','grade':None,'term':None,
       'stem':spec['stem'],'options':[{'key':k,'text':v} for k,v in choices],
       'answer':ans,'kind':'single_choice' if choices else kind,'has_missing_assets':False,
       'steps':spec['steps'],'difficulty':1,'knowledge_tags':[skill['name']],
       'type_tags':[spec['fine_type']],'curriculum_book_id':book,
       'curriculum_goal_ids':[goal],'foundation_skill_ids':[skill['id']],
       'provenance':{'dataset':'local_senior_foundations','source_id':qid,
          'url':f'local://senior-foundations/physics/{skill["id"]}',
          'license':'original author-created item','source_file':'original'}}
    choice=bool(choices)
    response='single_choice' if choice else 'calculation' if kind=='calculation' else 'short_answer'
    mode='choice' if choice else 'numeric' if kind=='calculation' else 'text'
    rubric_desc=spec.get('rubric','答案与题干条件相符，并说明必要的物理依据。')
    ann={'schema_version':1,'response_format':response,
       'knowledge':{'primary':[skill['name']],'supporting':[],'prerequisites':[]},
       'fine_types':[spec['fine_type']],
       'difficulty':{'level':1,'basis':spec.get('basis','只需辨认一个定义或完成一步计算。'),'origin':'luna','calibrated':False},
       'curriculum':{'grade':None,'term':None,'book_id':book,'goal_ids':[goal],
          'scope_status':'candidate','basis':f'按人教版课程目标 {goal} 映射；项目原创基础题，待Luna复核。'},
       'answer_spec':{'mode':mode,'accepted_answers':[ans],
          'equivalence':'exact' if choice else 'numeric' if kind=='calculation' else 'semantic',
          'constraints':['按选项作答。'] if choice else ['写出方向/单位或必要的解释。'],
          'unit':spec.get('unit'),'tolerance':0 if kind=='calculation' else None},
       'parts':[{'id':'p1','prompt':spec['stem'],'reference_answer':ans,
          'solution_steps':spec['steps'],'knowledge_tags':[skill['name']],
          'type_tags':[spec['fine_type']],'depends_on':[],'points':None,
          'rubric':[{'id':'evidence','description':rubric_desc,'points':None,'evidence_required':rubric_desc}],
          'common_errors':[{'description':spec.get('common_error','混淆相关物理量的定义、方向或单位。'),
             'knowledge_tags':[skill['name']],'type_tags':[spec['fine_type']]}]}],
       'grading':{'mode':'objective' if choice else 'ai_rubric','full_score':None,
          'allow_alternative_methods':True,'uncertainty_policy':'review_required'},
       'review':{'status':'candidate','answer_status':'checked','issues':[],'method':'item_read',
          'notes':'原创题；已逐题核算题干条件、唯一答案和解题步骤，候选标注不代表教师审核。'},
       'origin':{'model':'gpt-6-luna','batch_id':BATCH}}
    Annotation.model_validate(ann)
    solution=list(spec['steps'])
    return {'question_id':qid,'source_sha256':source_fingerprint(q),'decision':'passed',
       'quarantine_original':False,'question':q,'foundation_skill_ids':[skill['id']],
       'annotation':ann,'independent_solution':solution,'source_conflicts':[],
       'remaining_issues':[],'rationale':'原创题逐题复算：'+' '.join(solution)}

