skills.extend(EXTRA_SKILLS)

for s in skills:
    s['question_ids']=[f'local:senior-foundations:physics:{s["id"]}:q{i}' for i in range(1,len(s['questions'])+1)]
    for i,q in enumerate(s.pop('questions'),1):
        q['basis']=f'直接考查{q["fine_type"]}。'
        s.setdefault('_items',[]).append(item(s,q,i))
items=[it for s in skills for it in s.pop('_items')]
curriculum=json.loads((ROOT/'app/data/senior_curriculum.json').read_text())
physics_books=[b for b in curriculum['books'] if b['book_id'].startswith('physics-senior-')]
source_manifest=[{'path':b['source_archive'],'role':'curriculum scope','sha256':b['source_sha256']} for b in physics_books]
batch={'batch_id':BATCH,'source_manifest':source_manifest,'items':items}
prepare_batch(batch)
(ROOT/'app/data/senior_physics_foundations.json').write_text(json.dumps(batch,ensure_ascii=False,indent=2)+'\n')
(ROOT/'app/data/senior_physics_foundation_skills.json').write_text(json.dumps({'batch_id':BATCH,'skills':skills},ensure_ascii=False,indent=2)+'\n')
print(f'validated {len(items)} items, {len(skills)} skills across {len(physics_books)} physics books')
